from .subscription import Subscription

class Broker:
    def __init__(self):
        self._subscriptions = []
        self.dead_letters = []

    @property
    def dlq(self):
        return self.dead_letters

    def subscribe(self, subscription):
        self._subscriptions.append(subscription)
        return subscription

    def unsubscribe(self, subscription):
        self._subscriptions = [s for s in self._subscriptions if s is not subscription]

    def subscribe_regex(self, pattern, callback, retries=0):
        sub = Subscription(pattern, callback, retries=retries, is_regex=True)
        return self.subscribe(sub)

    def publish(self, topic, payload):
        for sub in list(self._subscriptions):
            if not sub.matches(topic):
                continue
            attempts = 0
            max_attempts = 1 + sub.retries
            success = False
            while attempts < max_attempts:
                attempts += 1
                try:
                    sub.callback(topic, payload)
                    success = True
                    break
                except Exception:
                    pass
            if not success:
                self.dead_letters.append((topic, payload, sub))

