import re

class Subscription:
    def __init__(self, topic_pattern, callback, retries=0, is_regex=False):
        self.topic_pattern = topic_pattern
        self.callback = callback
        self.retries = int(retries)
        self.is_regex = is_regex
        self._compiled = re.compile(topic_pattern) if is_regex else None

    def matches(self, topic):
        if self.is_regex and self._compiled:
            return bool(self._compiled.fullmatch(topic))
        pattern_segments = self.topic_pattern.split('.')
        topic_segments = topic.split('.')
        if len(pattern_segments) != len(topic_segments):
            return False
        return all(p == '*' or p == t for p, t in zip(pattern_segments, topic_segments))

