import unittest
from bus import Broker, Subscription

class TestEventBus(unittest.TestCase):
    def test_dlq_and_regex(self):
        broker = Broker()
        calls = {"flaky": 0}
        def flaky(t, p):
            calls["flaky"] += 1
            if calls["flaky"] <= 2: raise RuntimeError("flaky")
        broker.subscribe(Subscription("orders.*", flaky, retries=3))
        broker.publish("orders.created", {"id": 1})
        self.assertEqual(calls["flaky"], 3)
        self.assertEqual(broker.dlq, [])

        received = []
        broker.subscribe_regex(r"order\.[0-9]+\.created", lambda t, p: received.append(p))
        broker.publish("order.42.created", {"total": 5})
        self.assertEqual(received, [{"total": 5}])

if __name__ == '__main__': unittest.main()
